package com.erp.admin.order.util;

import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.PDImageXObject;

import javax.imageio.ImageIO;

import java.awt.image.BufferedImage;
import java.io.*;
import java.util.Arrays;
import java.util.Base64;
import java.util.List;

public class Base64ImagesToPdf {

	/**
	 * 将 Base64 图片列表写入 PDF，返回 PDF 的字节数组
	 *
	 * @param base64Images 图片 Base64 字符串列表
	 * @return 生成的 PDF 文件字节数组
	 */
	public static byte[] writeImagesToPdf(List<String> base64Images) throws IOException {
		try (PDDocument doc = new PDDocument();
			 ByteArrayOutputStream out = new ByteArrayOutputStream()) {

			for (String base64 : base64Images) {
				// 如果带有 "data:image/png;base64," 前缀，去掉
				if (base64.contains(",")) {
					base64 = base64.substring(base64.indexOf(",") + 1);
				}

				// 解码 Base64
				byte[] imageBytes = Base64.getDecoder().decode(base64);

				// 获取图片宽高（像素）
				BufferedImage bufferedImage = ImageIO.read(new ByteArrayInputStream(imageBytes));
				int imgWidthPx = bufferedImage.getWidth();
				int imgHeightPx = bufferedImage.getHeight();

				// 像素转厘米：规则 100px = 1cm
				float widthCm = imgWidthPx / 100.0f;
				float heightCm = imgHeightPx / 100.0f;

				// 厘米转 pt (1 cm = 28.3465 pt)
				float widthPt = widthCm * 28.3465f;
				float heightPt = heightCm * 28.3465f;

				// 创建页面，尺寸与图片对应
				PDPage page = new PDPage(new PDRectangle(widthPt, heightPt));
				doc.addPage(page);

				// 加载图片
				PDImageXObject pdImage = PDImageXObject.createFromByteArray(doc, imageBytes, "img");

				// 绘制图片
				try (PDPageContentStream contentStream = new PDPageContentStream(doc, page)) {
					contentStream.drawImage(pdImage, 0, 0, widthPt, heightPt);
				}
			}

			// 保存到内存字节流
			doc.save(out);
			return out.toByteArray();
		}
	}

	// 测试 main 方法
	public static void main(String[] args) throws IOException {
		List<String> images = Arrays.asList("", "");

		byte[] pdfBytes = writeImagesToPdf(images);

		// 写入文件验证
		try (FileOutputStream fos = new FileOutputStream("images_output.pdf")) {
			fos.write(pdfBytes);
		}
		System.out.println("PDF 已生成: images_output.pdf");
	}
}
